"""Tables of the experiment-2 prerequisite runs (issue #1193).

Reads anchor.json and runs/*.json and writes tables.md. Standard library
only:  python3 -I benchmarks/motor_optimization/summarize.py
"""
import json
from pathlib import Path

D = Path(__file__).resolve().parent
out = []
a = json.loads((D / "anchor.json").read_text())
an = a["anchor"]
p = a["provenance"]
out += ["# Experiment-2 prerequisites: tables", "",
        "Generated by `summarize.py` from `anchor.json` and `runs/`.", "",
        "## Anchor (θ0, primary validation model: h93 coupling torque, L2, g20)", "",
        "| quantity | value |", "|---|---|",
        f"| F0 (N² m²) | {an['F0']:.12e} |",
        f"| θ0 full-current mean (N m) | {an['mean0_full_current']:.12f} |",
        f"| mean floor = mean0 · 1.0025 (N m) | {an['mean_floor']:.12f} |",
        f"| T50 = 0.5 F0 | {an['targets']['T50']:.6e} |",
        f"| T90 = 0.1 F0 | {an['targets']['T90']:.6e} |",
        f"| T99 = 0.01 F0 | {an['targets']['T99']:.6e} |",
        f"| spaces A and B agree bit for bit | {a['spaces_agree_bitwise']} |",
        f"| commit | `{p['commit']}` (crates clean: {p['worktree_clean']}) |",
        f"| mesh | `{p['mesh']['file']}`, {p['mesh']['bytes']} bytes |",
        f"| mesh SHA-256 | `{p['mesh']['msh_sha256']}` |",
        f"| threads | RAYON={p['threads']['RAYON_NUM_THREADS']}, GEODE={p['threads']['GEODE_NUM_THREADS']}, faer {p['threads']['faer_par']} |",
        f"| rustc | {p['rustc']} |",
        f"| host load (1/5/15 min) at start | {p['host_load']} |",
        f"| primary validation solve wall time (s), A / B | {a['fe_unit_seconds']['space_a_solve_s']:.1f} / {a['fe_unit_seconds']['space_b_solve_s']:.1f} |",
        ""]
for k, v in [("A", a["validation_space_a"])]:
    out += [f"Per-current values (space {k}):", "", "| fraction | I_peak (A) | mean (N m) | std (N m) | std² |", "|---|---|---|---|---|"]
    for c in v["currents"]:
        out.append(f"| {c['fraction']} | {c['i_peak_A']:.6f} | {c['mean']:.12f} | {c['std']:.9e} | {c['std2']:.9e} |")
    out.append("")

out += ["## Reproduction of the #1182 records (same meshes)", "",
        "`max |dT|` is over every shared angle and current; `F rel` is over the three training currents.", "",
        "| run | design | config | mesh kind | F (this) | F (#1182) | F rel | max abs dT (N m) | max rel d mean |",
        "|---|---|---|---|---|---|---|---|---|"]
for f in sorted((D / "runs").glob("*.json")):
    r = json.loads(f.read_text())
    if f.name.startswith("fd_") or "validation" not in r:
        continue
    v = r["validation"]
    c = (r.get("compare") or {}).get("comparison")
    if c is None:
        continue
    out.append(f"| {f.stem} | {r['design']} | {v['config']['name']} | {v['mesh']['kind']} | "
               f"{c['F_new']:.9e} | {c['F_record']:.9e} | {c['F_rel']:.2e} | {c['max_abs_dT_Nm']:.2e} | {c['max_rel_dmean']:.2e} |")
out.append("")
ref = [json.loads(f.read_text()) for f in sorted((D / "runs").glob("*.json"))]
ref = [(f, r) for f, r in zip(sorted((D / "runs").glob("*.json")), ref) if r.get("status") == "refused"]
if ref:
    out += ["Refused (no value):", ""]
    for f, r in ref:
        out.append(f"- `{f.stem}`: {r['error']}")
    out.append("")

out += ["## Finite differences (training model h45, L1, g20, Newton 1e-12, frozen reference)", "",
        "| space | point | quantity | h | adjoint | FD | rel |", "|---|---|---|---|---|---|---|"]
for f in sorted((D / "runs").glob("fd_*.json")):
    r = json.loads(f.read_text())
    s = r["space"]["label"]
    for pt in r["points"]:
        for d in pt["directional"]:
            out.append(f"| {s} | {pt['label']} | dF/dt | {d['h']:g} | {d['adjoint_dF']:.9e} | {d['fd_dF']:.9e} | {d['rel_dF']:.2e} |")
            out.append(f"| {s} | {pt['label']} | dmean(1)/dt | {d['h']:g} | {d['adjoint_dmean1']:.9e} | {d['fd_dmean1']:.9e} | {d['rel_dmean1']:.2e} |")
        for cmp in pt["components"]:
            out.append(f"| {s} | {pt['label']} | dF/d{cmp['name']} | {cmp['h']:g} | {cmp['adjoint_dF']:.9e} | {cmp['fd_dF']:.9e} | {cmp['rel']:.2e} |")
out.append("")
(D / "tables.md").write_text("\n".join(out))
print("wrote", D / "tables.md")
